(function(){
  if (window.__projInstalled__) return;
  window.__projInstalled__ = true;
  var canvas = document.getElementById('projCanvas');
  var ctx = canvas.getContext('2d');
  var v0Slider = document.getElementById('v0Slider');
  var v0Val = document.getElementById('v0Val');
  var angSlider = document.getElementById('angSlider');
  var angVal = document.getElementById('angVal');
  var out = document.getElementById('projOut');
  var playBtn = document.getElementById('playBtn');
  var D2R = Math.PI / 180;
  var g = 10;
  var running = false, t = 0;
  window.simState = { v0: 30, alpha: 45, g: g, t: 0, running: false, x: 0, y: 0, T: 0, H: 0, R: 0, vx: 0, vy: 0 };
  function compute(){
    var v0 = parseFloat(v0Slider.value), alpha = parseFloat(angSlider.value);
    var vx0 = v0 * Math.cos(alpha * D2R), vy0 = v0 * Math.sin(alpha * D2R);
    var T = 2 * vy0 / g;
    var H = (vy0 * vy0) / (2 * g);
    var R = vx0 * T;
    window.simState.v0 = v0; window.simState.alpha = alpha;
    window.simState.T = T; window.simState.H = H; window.simState.R = R;
    window.simState.vx = vx0; window.simState.vy = vy0;
    return { v0: v0, alpha: alpha, vx0: vx0, vy0: vy0, T: T, H: H, R: R };
  }
  function groundY(){ return canvas.height - 40; }
  function scaleX(p, R){ var pad = 50; return pad + (p / (R || 1)) * (canvas.width - 2 * pad); }
  function scaleY(y, H){ var top = 24; var bottom = groundY(); var hmax = Math.max(H, 1); return bottom - (y / hmax) * (bottom - top); }
  function draw(){
    var p = compute();
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    var gy = groundY();
    ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(0, gy); ctx.lineTo(canvas.width, gy); ctx.stroke();
    ctx.fillStyle = '#64748b'; ctx.font = '12px sans-serif';
    ctx.fillText('O', 6, gy - 6);
    ctx.fillText('المدى R = ' + p.R.toFixed(1) + ' m', canvas.width - 180, gy - 6);
    var pts = [];
    var steps = 90;
    for (var i = 0; i <= steps; i++) {
      var tt = (i / steps) * p.T;
      var xx = p.vx0 * tt;
      var yy = p.vy0 * tt - 0.5 * g * tt * tt;
      if (yy < 0) yy = 0;
      pts.push([scaleX(xx, p.R), scaleY(yy, p.H)]);
    }
    ctx.strokeStyle = '#0d9488'; ctx.lineWidth = 2.5;
    ctx.beginPath();
    ctx.moveTo(pts[0][0], pts[0][1]);
    for (var j = 1; j < pts.length; j++) ctx.lineTo(pts[j][0], pts[j][1]);
    ctx.stroke();
    var cx = scaleX(window.simState.x, p.R);
    var cy = scaleY(window.simState.y, p.H);
    ctx.fillStyle = '#f59e0b';
    ctx.beginPath(); ctx.arc(cx, cy, 6, 0, Math.PI * 2); ctx.fill();
    ctx.strokeStyle = '#b45309'; ctx.lineWidth = 1.5;
    ctx.beginPath(); ctx.arc(cx, cy, 6, 0, Math.PI * 2); ctx.stroke();
    if (running) {
      var vx = p.vx0, vy = p.vy0 - g * t;
      var vscale = 4;
      var ax = cx + vx * vscale, ay = cy - vy * vscale;
      ctx.strokeStyle = '#dc2626'; ctx.lineWidth = 2.5;
      ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(ax, ay); ctx.stroke();
      ctx.fillStyle = '#dc2626';
      ctx.beginPath(); ctx.arc(ax, ay, 3.5, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = '#2563eb'; ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(ax, cy); ctx.stroke();
      ctx.strokeStyle = '#16a34a'; ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(ax, cy); ctx.lineTo(ax, ay); ctx.stroke();
    }
    v0Val.textContent = p.v0;
    angVal.textContent = p.alpha + '°';
    out.textContent = 'المدى R = ' + p.R.toFixed(1) + ' m | الذروة H = ' + p.H.toFixed(1) + ' m | زمن التحليق T = ' + p.T.toFixed(1) + ' s';
  }
  function loop(){
    if (running) {
      var p = compute();
      if (t > p.T || window.simState.y < 0) {
        t = 0;
        running = false;
        window.simState.running = false;
        playBtn.textContent = 'تشغيل القذف';
      } else {
        t += 0.03;
        window.simState.x = p.vx0 * t;
        window.simState.y = p.vy0 * t - 0.5 * g * t * t;
        if (window.simState.y < 0) window.simState.y = 0;
      }
      window.simState.t = t;
    }
    draw();
    requestAnimationFrame(loop);
  }
  playBtn.addEventListener('click', function(){
    if (!running) { t = 0; window.simState.x = 0; window.simState.y = 0; }
    running = !running;
    window.simState.running = running;
    playBtn.textContent = running ? 'إيقاف' : 'تشغيل القذف';
  });
  v0Slider.addEventListener('input', function(){});
  angSlider.addEventListener('input', function(){});
  function fit(){ canvas.style.maxWidth = '100%'; }
  if (!window.__fitInstalled__) { fit(); window.addEventListener('resize', fit); window.__fitInstalled__ = true; }
  loop();
})();
